<?php

namespace App\Libraries;

/**
 * Third batch of built-in knowledge: the situations users meet most often (where do I find..., sign-in and session
 * trouble, machine files, bonding results, printing, InterLink, calculators, data entry, browser trouble, generic
 * "it is not working" cases). Loaded by `php spark brain:seed`.
 */
class BrainSeed3
{
    /** @return list<array<string,mixed>> */
    public static function all(): array
    {
        $o = static fn (string $label, string $url, bool $admin = false): array => ['type' => 'open', 'label' => $label, 'url' => $url] + ($admin ? ['role' => 'admin'] : []);
        $k = static fn (string $title, string $keywords, string $body, array $steps = [], array $extra = []): array => array_merge(['title' => $title, 'keywords' => $keywords, 'body' => $body, 'steps' => $steps], $extra);
        $dtr = ['page_match' => 'dtr'];
        $il  = ['page_match' => 'interlink'];

        return [
            // ================================================================== where do I find...
            $k('Where do I find the calculators?', 'where calculators, where is the calculator, find calculators, open calculator, calculator location', 'Open QC Lab Reports in the sidebar, then the "Calculators & Standards" tab. The calculators for weight, specific gravity, compression set, DIN abrasion, Ross Flex and shrinkage are there.', [], $dtr + ['actions' => [$o('Open Calculators', 'dtr?tab=calculators')]]),
            $k('Where do I find the Report Designer?', 'where designer, where is the report designer, find designer, open designer, designer location, customize report where', 'The Report Designer is in the sidebar (admins only). If you cannot see it, your account is not an administrator.', [], ['role_min' => 'admin', 'actions' => [$o('Open Report Designer', 'designer', true)]]),
            $k('Where do I find the Help page?', 'where help, where is help, help page, find help, user guide, manual, guide location', 'Press "Help" in the sidebar for a quick guide of every section, or press the round help button at the bottom right to chat with the assistant.', [], ['actions' => [$o('Open Help', 'help')]]),
            $k('Where do I print a report?', 'where print, where do i print, find print button, print location, where is print preview, where to print report', 'Open the report (QC Lab Reports > Open Form), then press "Print / Preview Report" (material) or "Print / Preview Bonding Report" (bonding). The preview has Download PDF and Print buttons.', [], $dtr),
            $k('Where do I find my reports?', 'where reports, find my reports,where are my reports, ,  where are reports, all reports, report list, where are saved reports', 'All saved reports are in QC Lab Reports > Lab Tracker. Search by Lab Ref No. or press a category button to filter by type.', [], $dtr + ['actions' => [$o('Open Lab Tracker', 'dtr?tab=tracker')]]),
            $k('Where is the shoe bonding form?', 'where bonding, find bonding, bonding form location, where is u60 form, shoe bonding page', 'QC Lab Reports > "Shoe Bonding (U60)" tab, or "Shoe Bonding (U60)" in the sidebar under Lab Reports.', [], $dtr + ['actions' => [$o('Open Shoe Bonding', 'dtr?tab=bonding')]]),
            $k('Where do I find the material test forms?', 'where material forms, find fabric form, find leather form, material tests location, where is fabric report', 'QC Lab Reports > "Material Tests" tab (or "Material Tests" in the sidebar). Pick the form in "1. Select Material Test Form".', [], $dtr + ['actions' => [$o('Open Material Tests', 'dtr?tab=material')]]),
            $k('Where is InterLink Sync?', 'where interlink, find interlink, interlink location, open interlink, interlink page where', 'Press "InterLink Sync" in the sidebar (or the InterLink Sync button at the top of QC Lab Reports).', [], $il + ['actions' => [$o('Open InterLink Sync', 'interlink')]]),
            $k('Where is the Inbox?', 'where inbox, find inbox, messages where, chat where, open inbox, where are my messages', 'Press "Inbox" in the sidebar. The number on its icon shows unread messages.', [], ['actions' => [$o('Open Inbox', 'inbox')]]),
            $k('Where do I find the standards for a material?', 'where standards, find standard, standards list, look up standard value, where to see standards', 'Open QC Lab Reports > Calculators & Standards and use the Live Master Lookup Explorer, or open the report and press "Refresh & Apply Smart Standards" to see the standard applied to your material.', [], $dtr),
            $k('Where do I sign out?', 'where sign out, where logout, find sign out, log out button, how to leave, exit system', 'Press "Sign out" at the bottom of the sidebar (open it with the three-line button if it is hidden).'),
            $k('Where can I see my profile or my role?', 'my profile, my role, who am i, account info, signed in as, my account, my username', 'Your name and role are shown at the top right of every page, and the Dashboard lists "Signed in as" and your role.', [], ['page_match' => 'dashboard']),
            $k('How do I get started as a new user?', 'new user, getting started,how do i get started, get started, ,  first time, how to start, beginner, tour, learn the system, introduction', 'Start with the Help page for a short tour. Daily work happens in QC Lab Reports: find or create a report, load the machine results, check the ratings, save, then print or download the PDF. InterLink Sync is for sending results to InterLink.', ['Open Help for the overview.', 'Open QC Lab Reports > Lab Tracker.', 'Open a report or create a new one.', 'Ask this assistant whenever you are unsure.'], ['actions' => [$o('Open Help', 'help')]]),
            $k('What should I do first each day?', 'daily routine, every day, first thing, daily work, workflow, typical day, daily steps', 'Sign in, check the Dashboard and Inbox, open QC Lab Reports for the reports you are testing, load the machine results as tests finish, save, and print or download the finished reports. Sync to InterLink when the results are final.'),

            // ================================================================== generic "it is not working"
            $k('Something is not working', 'something not working, not working, problem, i have a problem, it is broken, doesnt work, system problem, need help, help me, error', 'Tell me what you were doing and what you saw, for example "Load Machine Results shows no file" or "PDF is blank". Meanwhile try these: reload with Ctrl + F5, check that you are still signed in, and read the message shown on the page. If it persists, press "Talk to an administrator".', ['Reload with Ctrl + F5.', 'Check that you are signed in.', 'Read the message at the top of the page.', 'Describe the problem here or press Talk to an administrator.']),
            $k('I need help', 'i need help, help, can you help me, please help, assist me, support needed, can someone help', 'I am here to help with NEXUS-L. Tell me what you want to do (for example "create a bonding report" or "print a PDF") or what went wrong, and I will guide you step by step.'),
            $k('I made a mistake, how do I undo it?', 'undo, mistake, wrong entry, revert, take back, entered wrong, made an error, oops', 'Nothing is permanent until you press Save. If you have not saved, reload the report from the Lab Tracker to discard the changes. If you already saved the wrong value, correct it and save again; if a record must be removed or restored, ask an administrator.', [], $dtr),
            $k('How do I delete a report?', 'delete report, remove report, erase record, delete record, remove lab ref, get rid of report', 'Reports cannot be deleted from the screen, to protect lab records. If a record was created by mistake, tell an administrator which Lab Reference No. it is.', [], $dtr),
            $k('I entered the wrong Lab Reference No.', 'wrong lab ref, typo lab ref, mistyped lab reference, change lab ref, edit lab ref, lab ref wrong saved', 'If you have not saved yet, correct the Lab Reference No. in the form. If it was already saved with the wrong number, do not create more copies: tell an administrator the wrong and the right number so the record can be corrected.', [], $dtr),
            $k('The same Lab Ref already exists', 'lab ref already exists, duplicate lab ref, already used, existing lab ref, same number twice', 'Search the Lab Tracker for that Lab Ref No. and open the existing report instead of creating a new one. A retest or the other shoe side has its own Lab Ref No.', [], $dtr),
            $k('How do I record a retest?', 'retest, re-test, repeat test, test again, second test, r01, redo test', 'A retest is saved as its own report with its own Lab Reference No., and its TR No. ends with -R01 in the lab\'s convention. Create it as a new record, load its machine file and save. Ask an administrator if you are unsure about the numbering.', [], $dtr),
            $k('Can I copy an existing report to make a new one?', 'copy report, duplicate report, clone report, copy record, reuse report, template report', 'There is no copy button. Create a new record, type the new Lab Reference No. and use Auto-Lookup and Load Machine Results to fill the details; this avoids copying old readings by mistake.', [], $dtr),
            $k('Do I need to fill every box?', 'required fields, mandatory fields, must fill, which fields required, optional fields, star fields, asterisk', 'Boxes marked with * (such as the Lab Reference No. and the Material Type) are needed. The others can stay empty if they do not apply. The system fills many of them for you.', [], $dtr),
            $k('How many decimals should I type?', 'decimals, decimal places, rounding, how many digits, number format, two decimals, precision', 'Readings are shown with 2 decimals. Type the value as measured; averages and ratings round themselves. Use a dot for decimals (3.25), not a comma.', [], $dtr),
            $k('I typed text in a number box', 'text in number box, letters in number, invalid number, nan, not a number, wrong format number, number field error', 'Number boxes accept digits and a decimal dot only. Remove letters, spaces and units (type 3.25, not "3.25 kg"). A dash "-" means no reading and should be left empty.', [], $dtr),
            $k('What are the units used?', 'units, kg/cm, mm, g/m2, measurement units, which unit, unit of measure, kgf', 'Bonding spots are in kg/cm (kgf/cm), thickness in mm, weight in g/m2, hardness in Shore A, and shrinkage and set in percent. The unit is shown next to each box.', [], $dtr),
            $k('What does a dash (-) in the machine file mean?', 'dash in file, minus sign file, hyphen reading, dash reading, no value dash, - in excel', 'A dash means that spot or test has no reading. NEXUS-L skips it and leaves the box empty.', [], $dtr),

            // ================================================================== machine file scenarios
            $k('How does NEXUS-L find the machine file for my Lab Ref?', 'how find machine file, file name rule, machine file name, which file is read, base lab ref file, file naming, file matches lab ref', 'It looks in the machine folder for a file named exactly like the Lab Ref No. (for example DTP20261012FAA8-L.xlsx), and if there is none, for the part before the first "-". Only .xlsx and .csv files are read.', [], $dtr),
            $k('My machine file is .xls', 'xls file, old excel, xls not read, excel 97, file extension xls, machine saves xls', 'Only .xlsx and .csv files are read. Open the .xls in Excel, "Save As" .xlsx with the same name in the same folder, then load again, or ask the person at the machine to save in .xlsx.', [], $dtr),
            $k('The file is open in Excel on the machine PC', 'file open excel, file locked, someone has the file open, excel lock, in use file, locked file', 'NEXUS-L only reads a copy of the file, so an open file is usually fine. If the loading fails, close the file on the machine PC and try again.', [], $dtr),
            $k('The machine file is there but values did not load', 'file exists nothing loaded,machine file there but nothing loaded, file is there but no values, ,  zero readings, loaded 0, no values from file, empty load, file found no values', 'The reading rule probably does not match the file layout (a different sheet, column or row). Tell an administrator the Lab Ref No.; they can compare the file with the Excel reader and fix the rule without any code change.', [], $dtr + ['diagnose' => 'machine_share']),
            $k('Machine results were loaded for the wrong sample', 'wrong sample loaded, wrong file loaded, other sample values, wrong readings loaded, loaded other lab ref', 'The loader uses exactly the Lab Ref No. in the box, so check it for typos and the -L / -R ending, then load again and compare one value with the machine file. Retest files have their own number.', [], $dtr),
            $k('Can I load the machine file again?', 'load again, reload machine file, reload results, load twice, reload readings, second load', 'Yes. Press Load Machine Results again; it replaces the readings with the latest file contents. Press Refresh & Apply Smart Standards afterwards and Save.', [], $dtr),
            $k('Which sheet of the Excel file is read?', 'which sheet, sheet name, excel sheet, u60.xls sheet, multiple sheets, sheet selection', 'For bonding the sheet named "U60.xls" is read (the first sheet if there is none). Other report types use the first sheet unless an administrator set another one in the Excel readers.', [], $dtr),
            $k('Do I need access to the machine PC?', 'machine pc access, share access, need access machine, network access, permission share, shared folder access', 'No. NEXUS-L reads the files from the shared location by itself. Only the server needs access to that location.', [], $dtr + ['diagnose' => 'machine_share']),
            $k('How long after the test is the file available?', 'how long file available, when file ready, delay file, wait for file, file after test, file time', 'The file appears when the machine saves it, normally right after the test ends. If it is not there, wait a minute and try again.', [], $dtr),
            $k('Load Machine Results is slow', 'load slow, machine load takes long, slow load results, waiting for machine file, long load', 'Reading the file from the shared location can take a few seconds the first time. If it takes more than a minute, tell an administrator; the location may be busy.', [], $dtr + ['diagnose' => 'machine_share']),

            // ================================================================== bonding scenarios
            $k('How is the age category decided from the style name?', 'age category style name, how is the age category decided, how is age category decided, adult children style, ua wm mn, uy td jn, infant, adult or children rule, style name rule', 'When the U60 file is loaded the style name decides: styles containing UA, WM or MN are Adult; styles containing UY, TD, JN or INFANT are Children; anything else is Adult. You can change the Age Category in the form.', [], $dtr),
            $k('The bonding result is FAIL but the values look fine', 'bonding fail good values, fail but values ok, wrong fail, why fail bonding, result fail check', 'Check the Age Category and Standard Spec: a Children style rated with the Adult standard (3.0) can fail. Also check that no spot has a very low value. Press "Recalculate Spots & Result" after correcting.', [], $dtr),
            $k('The standard shows 3 but this is a children shoe', 'wrong standard bonding, std 3 children, standard 2.5, change standard, standard wrong age', 'Change "Age Category" to Children (Standard Spec 2.5) and press "Recalculate Spots & Result". The result follows the new standard.', [], $dtr),
            $k('Some FiTO (center) values are empty', 'fito empty, center values missing, filler values missing, fito no value, center blank', 'FiTO has at most 13 spots and the machine only fills those it measured; a dash means no reading. Empty FiTO boxes are normal for styles without a filler.', [], $dtr),
            $k('The number of points on the diagram is wrong', 'wrong number of points, diagram points wrong, 26 points instead, wrong sketch, diagram does not match', 'The diagram is chosen from the highest UTF spot that has a value. If a high spot is empty or wrongly filled, correct the spot table and recalculate; the right diagram is then used.', [], $dtr),
            $k('Left and right reports show the same values', 'left right same values, both sides same, right shows left, side mixed up, left report right values', 'Each side has its own Lab Ref No. (-L and -R) and its own machine file. Check that you loaded the file of the right Lab Ref No. for that side.', [], $dtr),
            $k('Bonding report date is wrong', 'wrong date bonding, tested date wrong, date incorrect bonding, change date bonding, date from file', 'The Tested Date is read from the machine file; Received and Finished default to it. Correct the dates in the form and Save if they are not right.', [], $dtr),
            $k('The technician name is empty in bonding', 'technician empty, technician missing, no technician, tech name blank, equipment code no technician', 'The technician is filled from the equipment code in the machine file. If the code is new, an administrator adds it in Report Designer > File locations (equipment code to technician).', [], $dtr),
            $k('Can I enter a bonding report without a machine file?', 'bonding without file, manual bonding, type spots by hand, no machine file bonding, enter spots manually', 'Yes. Create the report, type the Lab Ref No., fill the information and enter the spot values by hand in the spot table, press "Recalculate Spots & Result" and Save.', [], $dtr),
            $k('What does Max Points mean?', 'max points, maxpoints, highest point, number of spots filled, points count', 'Max Points is the highest spot number that has a value. It decides which shoe diagram (26 to 34 points) is used on the report.', [], $dtr),
            $k('How do I check one spot value against the machine?', 'check spot value, verify value, compare with machine, spot check, verify reading machine file', 'Open the Excel readers in the Designer (admin) and use "Preview file" to see the real file, or ask the person at the machine. In the report, the spot table lists each value by spot number.', [], $dtr),

            // ================================================================== printing and pdf scenarios
            $k('The PDF has the wrong report data', 'pdf wrong data, pdf shows other report, wrong report in pdf, pdf old data, pdf not matching', 'The PDF is made from what is shown in the preview. Save the report first, reopen the preview and download again so the PDF shows the saved data.', [], $dtr),
            $k('The PDF file name is not what I want', 'pdf file name, rename pdf, pdf name, change pdf name, file name pdf', 'The file is named after the report title. Rename it in your Downloads folder after downloading.', [], $dtr),
            $k('How do I print several reports?', 'print many reports, batch print, print multiple, print all reports, print several lab refs', 'Open each report and print or download it one by one; there is no batch print yet. Tell an administrator if you need one.', [], $dtr),
            $k('The preview shows an old layout', 'old layout preview, preview old, layout not updated, preview not changed, designer change not shown preview', 'After an administrator changes the layout, reload with Ctrl + F5 and reopen the preview. If it still shows the old layout, tell the administrator to check that the layout was saved.', [], $dtr),
            $k('The signature lines are missing or cut', 'signature missing, signature cut, reviewed by line, approved by missing, bottom of report cut, footer cut', 'The bottom of the sheet has the Comments, Reviewed by and Approved by lines. If they are cut in a printout, set paper size A4, scale 100 % and margins "Default" in the print dialog, or use Download PDF.', [], $dtr),
            $k('Chinese characters show as boxes in the PDF', 'chinese characters, chinese boxes, squares instead of chinese, font missing, cn text, unicode pdf', 'The report has Chinese titles. If they show as boxes, the server is missing a Chinese font; tell an administrator so it can be installed.', [], $dtr),
            $k('Can I add my signature to the report?', 'signature on report, sign report, add signature, digital signature, stamp signature report', 'The sheet has signature lines for you to sign on paper after printing. Electronic signatures are not part of the report.', [], $dtr),

            // ================================================================== interlink scenarios
            $k('The Sign in to InterLink window did not open', 'window did not open, no window interlink, sign in button nothing, chrome did not open, no browser window, connect window missing', 'The sign-in window opens on the server PC, not on your computer. If you are not at the server, ask whoever is there to sign in, or to double-click tools\\Connect-InterLink.bat. The status turns green by itself afterwards.', [], $il + ['diagnose' => 'interlink_session']),
            $k('The InterLink sign-in window closed by itself', 'window closed itself, closed interlink window, window disappeared, sign in window closed, did not stay open', 'It closes by itself once you are signed in and the InterLink list appears: that means it worked. Check the Sync Center status. If you closed it before the list appeared, press Sign in to InterLink again.', [], $il + ['diagnose' => 'interlink_session']),
            $k('InterLink asks for a verification code', 'verification code interlink, mfa interlink, two factor interlink, otp interlink, code login interlink', 'That is InterLink\'s own security step. Complete it in the sign-in window as you normally would; NEXUS-L never sees your password or code.', [], $il),
            $k('The Sync Center says Connected but the queue stays waiting', 'queue waiting forever, queue not moving, queue stuck waiting, nothing prepared, queue pending long, not processing queue', 'Items are processed by the background worker about once a minute. Press "Run now" to process them immediately. If they still wait, the worker may be stopped; an administrator should check it.', [], $il + ['diagnose' => 'worker']),
            $k('The InterLink list is not up to date', 'interlink list old, not updated, stale grid, missing new applications, new application not shown, refresh interlink list', 'Press the reload button at the top of the InterLink portal view, or "Run now" in the Sync Center. If a brand-new application is still missing, wait a minute: the worker refreshes about once a minute.', [], $il + ['diagnose' => 'interlink_session']),
            $k('The Application No. I need is not in the list', 'application not in list, missing application, cannot find application no, search application not found, application missing', 'Use the filter boxes above the list and the page buttons, or type the Application No. in the Sync Center. If it truly is not there, it may not be created in InterLink yet: ask whoever submitted the request.', [], $il),
            $k('What should I do after syncing a Lab Reference?', 'after sync, next step after sync, what next sync, finish sync, after queue prepared, sync done what now', 'Check in InterLink that the data is correct, then complete the upload in the InterLink form (Upload Result tab) as usual. Sync History shows what was prepared and by whom.', [], $il),
            $k('Which fields does the sync fill?', 'which fields sync, fields filled interlink, what gets filled, sync fields list, data sent to interlink', 'It fills the InterLink form fields from the Lab Reference: report number, overall result, issue date, attachment name, supplier, style, product and material names, colour, material code and remarks. You can see and edit every field in the pre-sync dialog before confirming.', [], $il),
            $k('Why is the pre-sync dialog list empty?', 'dialog empty, no lab references dialog, combo empty, sync dialog no data, lab reference list empty', 'Choose "All Categories" in the filter and clear the quick search box; the list shows the latest 300 Lab References. If it is still empty, reload with Ctrl + F5.', [], $il),
            $k('Can I sync a bonding report to InterLink?', 'sync bonding, bonding interlink, send bonding report, bonding to interlink, shoe bonding sync', 'Yes. Whole shoe bonding Lab References are in the same list as material reports. Pick the Lab Reference in the Sync Center or the pre-sync dialog and use the Application No. of the request.', [], $il),
            $k('How do I stop the background sync?', 'stop sync, pause sync, stop worker, disable background, turn off sync', 'Use "Disconnect" in the Sync Center to forget the InterLink session; nothing is processed until you connect again. To stop the worker itself, an administrator disables the scheduled task "NEXUS-L InterLink Worker".', [], $il),
            $k('Is the InterLink password stored in NEXUS-L?', 'interlink password stored, store password, password saved interlink, credentials stored, is my interlink login saved', 'No. You sign in on InterLink\'s own page. NEXUS-L only keeps the session it receives (like a temporary pass) and uses it for the background reading.', [], $il),

            // ================================================================== calculators and standards
            $k('How do I use the Weight calculator?', 'weight calculator, calculate weight, raw weight, g/m2 calculator, fabric weight calc, weight calc use', 'In Calculators & Standards enter Raw Weight 1 to 3 (grams of the cut sample); the calculator gives Weight 1 to 3 in g/m2 and the average. Press "Apply to Material Form" to copy them into the open report.', ['Enter the three raw weights.', 'Read the g/m2 values and the average.', 'Press Apply to Material Form.'], $dtr),
            $k('How do I use the Specific Gravity calculator?', 'specific gravity calculator, sg calculator, calculate sg, raw weight thickness sg, sg calc use', 'Enter the raw weight and thickness of each of the 3 specimens; the calculator gives SG 1 to 3 and the average. Apply it to the open report with the button below the result.', [], $dtr),
            $k('How do I use the Compression Set calculator?', 'compression set calculator, calculate compression set, before after thickness, spacer calculator, compression calc use', 'Enter the thickness Before and After for each specimen and the spacer thickness; the calculator gives the compression set percentage for each and the average. Press "Apply to Material Form" to use it.', [], $dtr),
            $k('How do I use the DIN Abrasion calculator?', 'din calculator, abrasion calculator, calculate din, weight before after din, din calc use', 'Enter the weights before and after, the specific gravity (SG) and the SA value shown in the calculator; it gives the abrasion in mm3 using the formula printed under the title. Apply it to the open report.', [], $dtr),
            $k('How do I use the Ross Flex calculator?', 'ross flex calculator, flex calculator, cut growth calculator, initial final length, ross calc use', 'Enter the initial cut length (default 2.5 mm) and the final length for each specimen; the calculator gives the growth percentage. Apply it to the open report.', [], $dtr),
            $k('Apply to Material Form did nothing', 'apply to material form nothing, apply button not working, calculator apply fails, values not copied, calculator not copy', 'Open the material report first (Material Tests, with a Lab Ref loaded) and then press Apply: the values are copied into the open report. Check the Material Tests tab to see them, then Save.', [], $dtr),
            $k('The calculator result is different from my own calculation', 'calculator result differs, different answer calculator, calculation mismatch, wrong calculation, calculator wrong', 'Check the units and that you typed the values in the right boxes. The formula used is shown under each calculator title. If the numbers still differ, tell an administrator with the values you entered.', [], $dtr),
            $k('How does Refresh & Apply Smart Standards choose the standard?', 'smart standards how, which standard chosen, standard by thickness, material type standard, how standard applied, standard lookup rule', 'It looks up the standard by the Material Type and, where it applies, the thickness average, then fills the standard boxes and recalculates every rating. A wrong Material Type gives a wrong standard, so check it first.', [], $dtr),
            $k('A standard or rating box is empty', 'standard empty, rating empty, no standard, rating blank, std blank, standard missing', 'Fill the Material Type, enter the readings and press "Refresh & Apply Smart Standards". If the box stays empty there may be no standard for that material type; tell an administrator.', [], $dtr),
            $k('Who can change the standards?', 'change standards, edit standards, update standard value, standard values admin, who edits standards', 'Standards are part of the lab\'s master data and are changed by an administrator. If a standard looks wrong, tell an administrator the material type and the value you expected.', [], $dtr),

            // ================================================================== sign-in and session scenarios
            $k('I keep being sent back to the sign-in page', 'redirect login loop, back to sign in, login loop, keeps asking login, sign in page again, redirected login, loop login', 'This happens when the session is lost: you were idle for more than 30 minutes, cookies are blocked, or the clock is wrong. Sign in again, allow cookies for NEXUS-L, and avoid private/incognito windows.', ['Sign in again.', 'Allow cookies for this site.', 'Do not use a private window.', 'Tell an administrator if it keeps happening.']),
            $k('Please sign in to continue appears all the time', 'please sign in to continue, sign in message, flash sign in, asked to sign in repeatedly, sign in required message', 'The message appears when you open a page without an active session. Sign in; you are taken back to the page you wanted. If it appears again within minutes, check that cookies are allowed.'),
            $k('Can I stay signed in longer than 30 minutes?', 'longer session, extend session, idle timeout longer, stay signed in, session length, 30 minutes timeout', 'The idle timeout of 30 minutes is a security rule and counts from your last click. Tick "Remember me" on your own computer so a new sign-in happens automatically; shared computers should always sign out.'),
            $k('Can I be signed in on two computers?', 'two computers, two devices, same account twice, multiple login, sign in phone and pc', 'Yes, you can use your account on more than one device. Each keeps its own session. Sign out on shared computers.'),
            $k('My account was used by someone else', 'account hacked, someone used my account, unknown sign in, suspicious login, stolen account, security incident', 'Tell an administrator immediately and change your password with "Forgot password?". The Dashboard\'s recent activity lists your sign-ins so you can see which one was not yours.', [], ['page_match' => 'dashboard']),
            $k('The sign-in page says my account does not exist', 'account not found, user not found, no such user, unknown username, account does not exist', 'Check the spelling of your username or email. If you have not registered, press "Create one". If you registered and it still fails, ask an administrator.', [], ['page_match' => 'login']),

            // ================================================================== browser and device
            $k('Pop-ups or downloads are blocked', 'popup blocked, download blocked, browser blocks download, allow downloads, blocked pdf, pop up blocker', 'Click the blocked icon at the right of the address bar and choose Always allow for NEXUS-L, then try again. PDFs are normal downloads and need no pop-up.'),
            $k('How do I allow cookies for NEXUS-L?', 'allow cookies, cookies blocked, enable cookies, cookie settings, third party cookies, cookies off', 'In Chrome or Edge: click the lock icon next to the address, open Site settings, and set Cookies to Allow for this site. Reload and sign in.'),
            $k('The date or time on pages is wrong', 'wrong time, date wrong, time zone, clock wrong, time difference, incorrect time stamp', 'Dates and times come from the server. If your computer\'s clock is wrong, sessions can expire early: set your computer to automatic date and time.'),
            $k('How do I clear the browser cache?', 'clear cache, clear browser data, delete cache, empty cache, reset browser, cache problem', 'Press Ctrl + Shift + Delete, choose "Cached images and files", and clear. For one page, Ctrl + F5 is enough.'),
            $k('Which screen size works best?', 'screen size, resolution, best screen, monitor size, zoom level, display size', 'A desktop screen of 1366 px width or more is best for data entry. Use the sidebar collapse button (three lines) to get more room. Phones and tablets work for viewing and quick checks.'),
            $k('The text is cut off on my small screen', 'text cut small screen, cut off phone, truncated, overflow screen, cannot see all, hidden text small screen', 'Scroll sideways inside tables, collapse the sidebar, or zoom out with Ctrl and -. On phones the menu is behind the three-line button.'),
            $k('Is there a keyboard shortcut?', 'keyboard shortcut, shortcuts, hotkeys, keys, press key, quick keys', 'Useful keys: Ctrl + F5 reloads the page completely, Escape closes the assistant and dialogs, Tab moves between boxes (in lookup boxes it also looks the code up), and in the Designer the arrow keys nudge the selected item.'),

            // ================================================================== inbox details
            $k('How do I edit or delete a message I sent?', 'edit message, delete message, change message, unsend, remove message chat, correct message', 'Open the message menu in the Inbox (hover the message) to edit it. Use "Forward" to send it to someone else. Ask an administrator if a message must be removed.', [], ['page_match' => 'inbox']),
            $k('How do I pin or search messages in a chat?', 'pin message, search chat, find message, pinned messages, search in conversation, chat search', 'Use the message menu to pin a message and the chat details panel to see pinned messages, media and to search inside the conversation.', [], ['page_match' => 'inbox']),
            $k('What is Secure Messaging in the Inbox?', 'secure messaging, encrypted chat, secure chat, encryption chat, unencrypted, secured chat', 'Secure Messaging encrypts the messages of that chat. Turning it off sends future messages as plain text, so the Inbox asks you to confirm.', [], ['page_match' => 'inbox']),
            $k('Can messages disappear automatically?', 'disappearing messages, auto delete messages, timer messages, messages vanish, temporary messages', 'Yes, a chat can be set to disappearing messages in the chat details panel; messages then remove themselves after the chosen time.', [], ['page_match' => 'inbox']),
            $k('I do not see a colleague in the Inbox list', 'colleague missing inbox, user not in list, cannot find person chat, search people no result, person missing chat', 'Type their name in "Search people". If they still do not appear, they may not have an account yet or are in a different system; ask an administrator.', [], ['page_match' => 'inbox']),

            // ================================================================== admin situations
            $k('A user cannot see a page or button', 'user cannot see page, user missing button, user no access, user cannot open, why cannot user see, role missing button', 'Admin-only pages (Report Designer, Brain) are visible only to administrators. For other pages, ask the user to reload with Ctrl + F5 and check they are signed in with their own account.', [], ['role_min' => 'admin']),
            $k('I changed the layout but users still see the old one', 'layout not applied users, designer change not visible, users old layout, saved layout not showing, layout cache', 'Check that you pressed "Save layout" and saw "Saved". Users see it the next time they open the report; if not, they reload with Ctrl + F5. Check that you edited the same point count as the report uses.', [], ['role_min' => 'admin', 'page_match' => 'designer']),
            $k('How do I update the machine file reading rules after a machine change?', 'machine changed rules, update reading rules, new machine format admin, change excel mapping, machine upgrade rules', 'Use Report Designer > Excel readers: pick the report type, preview a real file, click the cells for each rule, press Test, then Save readers. It takes effect immediately for "Load Machine Results".', [], ['role_min' => 'admin', 'page_match' => 'designer']),
            $k('How do I see what a user did before a problem?', 'user activity before problem, what did user do, activity trail, user actions, see user history admin', 'In Brain > Chats open the user\'s conversation: "What the user did just before" lists their last pages, buttons and errors with times.', [], ['role_min' => 'admin', 'page_match' => 'brain']),
            $k('How do I mark a problem as fixed in Brain?', 'resolve problem brain, mark fixed, close issue, problem resolved, issue fixed brain', 'In Brain > Problems press "Write the fix" to save the solution (the assistant then uses it) or "Ignore" for a harmless one. Either removes it from the open list.', [], ['role_min' => 'admin', 'page_match' => 'brain']),
            $k('How do I remove a wrong answer from the assistant?', 'remove wrong answer bot, retire answer, wrong knowledge, delete answer assistant, fix bad answer', 'Brain > Knowledge: find the answer, press Edit to correct it, or Retire so it is no longer used.', [], ['role_min' => 'admin', 'page_match' => 'brain']),
            $k('How do I see what users ask the assistant most?', 'popular questions, most asked, bot analytics, top questions, assistant usage, frequent questions', 'Brain > Knowledge lists each answer with how many times it was used and how many found it helpful; Brain > Unanswered lists what it could not answer, with counts.', [], ['role_min' => 'admin', 'page_match' => 'brain']),
            $k('How do I restore the assistant after a disk problem?', 'restore brain, disaster recovery assistant, recover knowledge, lost knowledge, rebuild brain, restore from back file', 'Brain > Health > "Restore knowledge from knowledge.back" rebuilds the answers from the latest copy in D:\\html\\Brain or C:\\Brain. The Brain mirror on C: is there for exactly this case.', [], ['role_min' => 'admin', 'page_match' => 'brain', 'diagnose' => 'brain']),
            $k('The server was restarted: what must be running?', 'after restart, server restart checklist, services to start, apache mysql start, what to start, reboot server', 'After a reboot make sure Apache and MySQL are running. The scheduled task "NEXUS-L InterLink Worker" starts by itself; check Brain > Health. If the InterLink status is red, sign in to InterLink again in the Sync Center.', [], ['role_min' => 'admin', 'diagnose' => 'worker']),
            $k('How do I check the error log?', 'error log, logs, server log, where logs, check log, php errors, log files', 'Application logs are in writable/logs (one file per day); Apache errors are in the Apache logs folder. Brain > Problems already groups the errors users hit, which is a good place to start.', [], ['role_min' => 'admin']),
            $k('How do I update NEXUS-L safely?', 'update system, deploy update, upgrade nexus-l, release update, install update, apply changes', 'Back up the project folder and the database, copy the new files, run php spark migrate and php spark brain:seed, run php spark deploy:check, and ask users to reload with Ctrl + F5. Keep the previous copy for a quick rollback.', ['Back up folder and database.', 'Copy the new files.', 'Run migrate and brain:seed.', 'Run deploy:check.', 'Ask users to press Ctrl + F5.'], ['role_min' => 'admin']),
            $k('How do I move NEXUS-L to a new server?', 'move server, new server, migrate nexus-l, change server, relocate system, install new pc', 'Install XAMPP (Apache, PHP 8, MariaDB), copy the project and the dbnexus database, set the address in .env, run php spark migrate and php spark deploy:check, register the worker task with tools\\interlink-worker.ps1, install Chrome and Node, and set the machine-file location in the Designer.', [], ['role_min' => 'admin']),
            $k('How do I make the system faster?', 'make faster, speed up, improve performance, slow system admin, performance tuning, optimize', 'Keep NEXUS-L and its sessions on the SSD, turn on Apache compression (mod_deflate), keep production mode on, rebuild the minified scripts (node tools\\build\\build.js), and check Brain > Health for disk space and the worker.', [], ['role_min' => 'admin', 'diagnose' => 'disk']),
            $k('Which PHP and Apache settings matter?', 'php settings, apache settings, php ini, memory limit, max execution, settings recommended, server config', 'PHP memory_limit of at least 256M, the zip, curl, mysqli, mbstring and intl extensions, Apache modules rewrite, headers and deflate enabled, and production mode. php spark deploy:check shows each one.', [], ['role_min' => 'admin']),

            // ================================================================== misc common questions
            $k('Why is the page title different from the menu name?', 'page title different, menu name different, title mismatch, naming, qc lab reports dtr', 'The sidebar item "QC Lab Reports (DTR)" opens the page titled "QC Lab Digital Test Reports"; DTR stands for Digital Test Reports. Both are the same place.'),
            $k('What is DTR?', 'dtr, what is dtr, digital test report, qc lab digital test reports, dtr meaning', 'DTR means Digital Test Reports: the part of NEXUS-L where lab reports are created, calculated and printed (Lab Tracker, Material Tests, Shoe Bonding, Calculators & Standards).', [], $dtr),
            $k('What does the number next to Lab Tracker mean?', 'number next to lab tracker, count lab tracker, 4568, tab count, total count tab', 'It is the total number of lab reports in NEXUS-L. The category buttons show how many there are of each type.', [], $dtr),
            $k('What does "Master Lookup Records" mean?', 'master lookup records, 271627, lookup records, master data count, lookup count card', 'It is the number of master data rows the system can look up: DSR, shoe, material and standard records used to fill your reports automatically.', [], $dtr),
            $k('Why are there two numbers for bonding reports?', 'two numbers bonding, 1085 1091, count different, bonding count mismatch, different counts', 'The Lab Tracker counts bonding reports that have spot results, while other screens may count every bonding test record. A small difference is normal.', [], $dtr),
            $k('How current is the data in NEXUS-L?', 'how current data, data up to date, latest data, is data live, data freshness, updated when', 'Reports are live: what is saved appears immediately for everyone. The machine files are read when you press Load Machine Results, and InterLink data is refreshed about once a minute.'),
            $k('Who do I contact for training?', 'training, learn nexus-l, who teaches, tutorial, how to learn, user training', 'Start with the Help page and this assistant. For hands-on training or new procedures, ask an administrator.', [], ['actions' => [$o('Open Help', 'help')]]),
            $k('Can I suggest a new feature?', 'suggest feature, feature request, new idea, improvement request, wish, add feature', 'Yes. Press "Talk to an administrator" and describe what would help you; administrators collect these requests.'),
            $k('The assistant window is in my way', 'bot in the way, assistant covers, chat blocks, hide assistant button, move chat window', 'Press × or Escape to close it; only the small round button stays at the bottom right. It never appears in printouts.'),
            $k('Is the assistant connected to the internet?', 'assistant internet, bot online, cloud ai, does bot use ai, privacy of assistant, where does bot run', 'No. The assistant runs entirely on the NEXUS-L server and uses only the knowledge saved there; nothing you ask leaves the lab network.'),
            $k('How do I tell the assistant what I want to do?', 'how to ask assistant, how to phrase question, ask properly, how to use assistant, assistant tips', 'Write normally, for example "how do I print a bonding PDF", "machine file not found for DTP20261012FAA8-L", or "open DTP20261012FAA8-L". Short, specific sentences work best.'),
        ];
    }
